head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[ModelUtil > M > getRefToReqData]<br/>Submission 객체의 ref 속성을 Request 문자열로 변환하여 반환합니다.",
    "validation" : [
        "submission(필수) 파라미터로 Submission 객체를 설정할 수 있어야 합니다.",
        "Submission 의 ref 설정에 따라 변환된 Request 문자열을 반환해야 합니다.",
        "Submission 의 requestData 를 null 로 초기화한 후 ref 속성 기반으로 요청 데이터를 생성해야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_getRefToReqData_onclick = function () {
    var scenario = par_scenario.getValue();

    if (scenario === "1") {
        // 시나리오 1 : 가이드 예제 - submission 객체로 호출, ref 기반 Request 문자열 반환
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : 가이드 예제 - ref 기반 Request 문자열 반환 ──");

        var sub = WebSquare.ModelUtil.getSubmission("sbm_test");
        var reqData = WebSquare.ModelUtil.getRefToReqData(sub);

        wf_body_bottom.getObj("scwin").setReturnValue("submission.ref : " + sub.ref);
        wf_body_bottom.getObj("scwin").setReturnValue("반환 타입 : " + (typeof reqData));
        wf_body_bottom.getObj("scwin").setReturnValue("반환 Request 문자열 : " + reqData);
    } else if (scenario === "2") {
        // 시나리오 2 : @spec 검증 - 미리 설정된 requestData 가 null 로 초기화된 후 ref 기반 재생성
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : 미리 설정된 requestData → null 초기화 후 ref 기반 재생성 (@spec) ──");

        var sub = WebSquare.ModelUtil.getSubmission("sbm_test");
        sub.requestData = { "PRESET_KEY" : "PRESET_VALUE" };
        wf_body_bottom.getObj("scwin").setReturnValue("호출 전 submission.requestData : " + JSON.stringify(sub.requestData));

        var reqData = WebSquare.ModelUtil.getRefToReqData(sub);

        wf_body_bottom.getObj("scwin").setReturnValue("호출 후 submission.requestData : " + JSON.stringify(sub.requestData) + " (null 초기화 확인)");
        wf_body_bottom.getObj("scwin").setReturnValue("반환 Request 문자열 : " + reqData + " (PRESET_VALUE 미포함, ref 기반 dma_request 사용)");
    }
};
